previewCss:
.darma-loader-darma-b10-ink-drop-spread { --accent: var(--loader-color, #1e293b); --accent-2: var(--loader-secondary-color, #6366f1); width: var(--loader-size, 76px); height: var(--loader-size, 76px); position: relative; display: grid; place-items: center; }
.darma-loader-darma-b10-ink-drop-spread span { position: absolute; width: 22%; height: 22%; border-radius: 50%; background: radial-gradient(circle at 40% 35%, color-mix(in srgb, #fff 22%, var(--accent)), var(--accent)); animation: darma-loader-darma-b10-ink-drop-spread-ink calc(var(--loader-speed, 1s) * 2.2) ease-out infinite; }
.darma-loader-darma-b10-ink-drop-spread span:nth-child(2) { background: radial-gradient(circle at 40% 35%, color-mix(in srgb, #fff 22%, var(--accent-2)), var(--accent-2)); animation-delay: calc(var(--loader-speed, 1s) * 1.1); }
@keyframes darma-loader-darma-b10-ink-drop-spread-ink { 0% { transform: scale(.2); border-radius: 50%; opacity: 1; } 55% { border-radius: 42% 58% 45% 55%; } 100% { transform: scale(3.4); border-radius: 46% 54% 52% 48%; opacity: 0; } }

